import{_ as i,o as a,c as t,ae as r}from"./chunks/framework.ivNTQwfq.js";const m=JSON.parse('{"title":"Matriz de Priorización de Incidentes","description":"","frontmatter":{},"headers":[],"relativePath":"soporte/1_priorizacion_incidentes.md","filePath":"soporte/1_priorizacion_incidentes.md"}'),o={name:"soporte/1_priorizacion_incidentes.md"};function d(n,e,s,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="matriz-de-priorizacion-de-incidentes" tabindex="-1">Matriz de Priorización de Incidentes <a class="header-anchor" href="#matriz-de-priorizacion-de-incidentes" aria-label="Permalink to &quot;Matriz de Priorización de Incidentes&quot;">​</a></h1><p>Este documento establece los criterios de clasificación para categorizar incidentes entrantes en el sistema ServiceNow de SURA. La matriz define tres niveles de prioridad (Alta, Media, Baja) basados en el impacto operativo, permitiendo una gestión eficiente y ordenada de las solicitudes de soporte.</p><table tabindex="0"><thead><tr><th>Prioridad</th><th>Definición de la prioridad</th></tr></thead><tbody><tr><td>Alta</td><td>El servicio está interrumpido. Los procesos de negocio que lo utilizan no pueden realizarse. Pérdida total de servicio. No hay forma alternativa de trabajar.</td></tr><tr><td>Media</td><td>La incidencia bloquea la operatividad o el rendimiento del servicio se ha degradado, no existiendo un camino alternativo viable que permita al usuario realizar su operación habitual.</td></tr><tr><td>Baja</td><td>Los procesos de negocio o el desarrollo de sus trabajos, se realiza con menor efectividad.</td></tr></tbody></table>',3)])])}const u=i(o,[["render",d]]);export{m as __pageData,u as default};
